import{d as g,C as e,o as m,c as h,a3 as i,E as a,j as t,a as u}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"论语·八佾","description":"《论语》第 3 篇「八佾」——二十六章原文与导读。礼乐之本、绘事后素、祭如在、尽善尽美，孔子论礼最深的一篇。","frontmatter":{"title":"论语·八佾","description":"《论语》第 3 篇「八佾」——二十六章原文与导读。礼乐之本、绘事后素、祭如在、尽善尽美，孔子论礼最深的一篇。","category":"guide","aliases":["八佾","八佾篇","八佾第三","论语八佾","lunyu 八佾"],"source":["《论语》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/lunyu/chapter-03.md","filePath":"lizhimingde/sishu-wujing/lunyu/chapter-03.md","lastUpdated":1790316338000}'),y={name:"lizhimingde/sishu-wujing/lunyu/chapter-03.md"},x=g({...y,setup(d){const s=[{id:"yi",label:"一、八佾舞于庭",showLabel:!0,sentences:[["孔子谓季氏：“",{text:"八佾",glossary:"bayi"},"舞于庭，是可忍也，",{text:"孰",glossary:"shu"},"不可忍也？”"]],note:"孔子论季氏：「八佾舞于庭，是可忍也，孰不可忍也？」——八佾是天子之舞（八行八列，六十四人），季氏为鲁国大夫却用天子之礼。这样的事都忍心做得出来，还有什么事做不出来？此章斥僭越。"},{id:"er",label:"二、三家者以《雍》彻",showLabel:!0,sentences:[["三家者以《雍》",{text:"彻",glossary:"che"},"。子曰：“‘相维辟公，天子",{text:"穆穆",glossary:"mumu"},"’，奚取于三家之堂？”"]],note:"鲁国三家（仲孙、叔孙、季孙）祭祖时用《雍》诗撤祭。而《雍》是天子祭宗庙之诗，其中有「相维辟公，天子穆穆」（助祭者是诸侯，天子端庄肃穆）；孔子遂问：「奚取于三家之堂？」——这样的句子，用在三家的堂上取它什么？亦斥僭越。"},{id:"san",label:"三、人而不仁，如礼何",showLabel:!0,sentences:[["子曰：“人而不仁，如礼何？人而不仁，如乐何？”"]],note:"「人而不仁，如礼何？人而不仁，如乐何？」——人若没有仁心，礼对他有何用？乐对他有何用？此章点明礼乐之本在仁；无仁，则礼乐只成空壳。"},{id:"si",label:"四、礼之本",showLabel:!0,sentences:[["林放问礼之本，子曰：“大哉问！礼，与其",{text:"奢",glossary:"she"},"也，宁俭；丧，与其",{text:"易",glossary:"yi-sang"},"也，宁",{text:"戚",glossary:"qi"},"。”"]],note:"林放问礼之本。孔子先赞「大哉问」，然后答：「礼，与其奢也，宁俭；丧，与其易也，宁戚」——礼与其奢侈，宁可俭朴；丧事与其仪节周备（易＝治、办得周全），宁可哀戚。此章指出礼之本在真情而非形式。"},{id:"wu",label:"五、夷狄之有君",showLabel:!0,sentences:[["子曰：“夷狄之有君，不如诸夏之亡也。”"]],note:"「夷狄之有君，不如诸夏之亡也」——夷狄纵有君主，也不如中原诸国没有君主。诸夏虽偶或无君，而礼义尚在；夷狄虽有君，而无礼义。此章以礼义为文明之本。"},{id:"liu",label:"六、曾谓泰山不如林放乎",showLabel:!0,sentences:[["季氏",{text:"旅",glossary:"lv"},"于泰山。子谓冉有曰：“女弗能救与？”对曰：“不能。”子曰：“呜呼！曾谓泰山不如林放乎？”"]],note:"季氏要去祭泰山（旅＝祭山川）。孔子对冉有说：「女（汝）弗能救与」——你不能阻止吗？冉有答「不能」。孔子叹：「呜呼！曾谓泰山不如林放乎」——难道泰山之神还不如林放（懂得问礼之本）吗？言泰山必不受此非礼之祭。"},{id:"qi",label:"七、其争也君子",showLabel:!0,sentences:[["子曰：“君子无所争，必也射乎！",{text:"揖让",glossary:"yirang"},"而升，下而饮。其争也君子。”"]],note:"「君子无所争，必也射乎」——君子无所争，若有，那一定是射箭吧。「揖让而升，下而饮」——升堂比射时彼此揖让，射罢下来一同饮酒。「其争也君子」——那样的争，也是君子之争。写「争」中之礼让。"},{id:"ba",label:"八、绘事后素",showLabel:!0,sentences:[["子夏问曰：“‘巧笑",{text:"倩",glossary:"qian"},"兮，美目",{text:"盼",glossary:"pan"},"兮，素以为绚兮’何谓也？”子曰：“",{text:"绘事后素",glossary:"huishihousu"},"。”曰：“礼后乎？”子曰：“起予者商也！始可与言《诗》已矣。”"]],note:"子夏问：「巧笑倩兮，美目盼兮，素以为绚兮」是什么意思？孔子答：「绘事后素」——先有白底，然后施彩绘。子夏即问：「礼后乎？」——那么礼也是在后的吧？孔子赞曰：「起予者商也！始可与言《诗》已矣」——能启发我的是卜商啊，现在可以与你谈《诗》了。此章言仁先礼后。"},{id:"jiu",label:"九、文献不足故也",showLabel:!0,sentences:[["子曰：“夏礼吾能言之，杞不足征也；殷礼吾能言之，宋不足征也；",{text:"文献",glossary:"wenxian"},"不足故也，足则吾能征之矣。”"]],note:"「夏礼吾能言之，杞不足征也；殷礼吾能言之，宋不足征也」——夏礼我能说，但杞国（夏之后）不足以取证；殷礼我能说，但宋国（殷之后）亦不足取证。「文献不足故也，足则吾能征之矣」——是典籍与贤人不足之故；若足，我便能验证了。"},{id:"shi",label:"十、禘自既灌而往者",showLabel:!0,sentences:[["子曰：“",{text:"禘",glossary:"di"},"自既",{text:"灌",glossary:"guan"},"而往者，吾不欲观之矣。”"]],note:"「禘自既灌而往者，吾不欲观之矣」——禘祭自第一次献酒（灌）之后，我就不想再看下去了。禘是天子之大祭，鲁国僭行，故孔子不忍观。"},{id:"shiyi",label:"十一、知其说者之于天下也",showLabel:!0,sentences:[["或问禘之说。子曰：“不知也。知其说者之于天下也，其如示诸斯乎！”指其掌。"]],note:"有人问禘祭之义。孔子答「不知也」，然后说：「知其说者之于天下也，其如示诸斯乎！」——懂得禘祭之义者，看天下就如看这里一样清楚；说着「指其掌」。以掌喻易，极言禘义之大。"},{id:"shier",label:"十二、祭如在",showLabel:!0,sentences:[["祭如在，祭神如神在。子曰：“吾不与祭，如不祭。”"]],note:"「祭如在，祭神如神在」——祭祖先如同祖先就在，祭神如同神就在。孔子又说：「吾不与祭，如不祭」——我若未亲自参与祭祀，便等于没有祭。所重者「亲在」与「诚」。"},{id:"shisan",label:"十三、获罪于天，无所祷也",showLabel:!0,sentences:[["王孙贾问曰：“与其",{text:"媚",glossary:"mei"},"于",{text:"奥",glossary:"ao"},"，宁媚于",{text:"灶",glossary:"zao"},"，何谓也？”子曰：“不然，获罪于天，无所祷也。”"]],note:"王孙贾问：「与其媚于奥，宁媚于灶」（与其讨好屋内西南隅之神，不如讨好灶神）是什么意思？孔子答：「不然，获罪于天，无所祷也」——不然；若得罪了天，便无处可祷了。言祷不在媚神，而在合于天理。"},{id:"shisi",label:"十四、郁郁乎文哉",showLabel:!0,sentences:[["子曰：“周",{text:"监",glossary:"jian"},"于二代，",{text:"郁郁乎文哉",glossary:"yuyuhuwenzai"},"！吾从周。”"]],note:"「周监于二代，郁郁乎文哉！吾从周」——周朝礼制取鉴于夏、商二代（监＝视、借鉴），文采何等丰盛！我遵从周。此章明孔子之取法。"},{id:"shiwu",label:"十五、子入太庙，每事问",showLabel:!0,sentences:[["子入太庙，每事问。或曰：“孰谓",{text:"鄹人之子",glossary:"zourenzhizi"},"知礼乎？入太庙，每事问。”子闻之，曰：“是礼也。”"]],note:"「子入太庙，每事问」——孔子入太庙，每事都要问。有人说：「孰谓鄹人之子知礼乎？」（谁说这鄹邑人的儿子懂礼？）入太庙却事事都问。孔子闻之曰：「是礼也」——这正是礼啊。言敬慎即是礼。"},{id:"shiliu",label:"十六、射不主皮",showLabel:!0,sentences:[["子曰：“射不主",{text:"皮",glossary:"pi"},"，为力不同科，古之道也。”"]],note:"「射不主皮，为力不同科，古之道也」——射箭不以穿透箭靶之皮为主（主＝以之为尚），因为各人力气不等（科＝等）；这是古之道。射礼所重在中不在力。"},{id:"shiqi",label:"十七、尔爱其羊，我爱其礼",showLabel:!0,sentences:[["子贡欲去告朔之",{text:"饩羊",glossary:"xiyang"},"。子曰：“赐也！尔爱其羊，我爱其礼。”"]],note:"「子贡欲去告朔之饩羊」——子贡想把每月朔日告庙所用的活羊去掉（饩羊＝告朔所供之羊）。孔子说：「赐也！尔爱其羊，我爱其礼」——你爱惜那只羊，我爱惜那礼。言礼之形式亦不可轻废。"},{id:"shiba",label:"十八、事君尽礼",showLabel:!0,sentences:[["子曰：“事君尽礼，人以为谄也。”"]],note:"「事君尽礼，人以为谄也」——服事君主而尽礼，别人反以为谄媚。此章慨叹时人不知礼。"},{id:"shijiu",label:"十九、君使臣以礼",showLabel:!0,sentences:[["定公问：“君使臣，臣事君，如之何？”孔子对曰：“君使臣以礼，臣事君以忠。”"]],note:"鲁定公问：「君使臣，臣事君，如之何？」孔子答：「君使臣以礼，臣事君以忠」——君以礼使臣，臣以忠事君。君臣之义是双向的。"},{id:"ershi",label:"二十、乐而不淫",showLabel:!0,sentences:[["子曰：“《关雎》，乐而不",{text:"淫",glossary:"yin-yue"},"，哀而不伤。”"]],note:"「《关雎》，乐而不淫，哀而不伤」——《关雎》一篇，快乐而不过度（淫＝过度），哀而不至伤身。此为以「中」评诗乐之准。"},{id:"ershiyi",label:"二十一、既往不咎",showLabel:!0,sentences:[["哀公问社于宰我，宰我对曰：“夏后氏以松，殷人以柏，周人以栗，曰使民战栗。”子闻之，曰：“成事不说，遂事不谏，既往不",{text:"咎",glossary:"jiu"},"。”"]],note:"哀公问社（社主之木）于宰我。宰我答：夏后氏用松，殷人用柏，周人用栗，「曰使民战栗」（说是使民战栗）。孔子闻之曰：「成事不说，遂事不谏，既往不咎」——已做成的不必再说，已做完的不必再谏，已过去的不必再追究。"},{id:"ershier",label:"二十二、管仲之器小哉",showLabel:!0,sentences:[["子曰：“管仲之器小哉！”或曰：“管仲俭乎？”曰：“管氏有三归，官事不",{text:"摄",glossary:"she-guan"},"，焉得俭？”“然则管仲知礼乎？”曰：“邦君树",{text:"塞门",glossary:"saimen"},"，管氏亦树塞门；邦君为两君之好，有",{text:"反坫",glossary:"fandian"},"。管氏亦有反坫，管氏而知礼，孰不知礼？”"]],note:"孔子评管仲：「管仲之器小哉！」有人问「管仲俭乎」，孔子答：管氏有三归（三处府库）、管事者不兼职（不摄），哪算俭？又问「管仲知礼乎」，答：国君门前立屏（树塞门），管氏亦立；国君为两君之好设反坫（反坫＝宴饮时置空酒杯的土台），管氏亦有——管氏若知礼，谁还不知礼？"},{id:"ershisan",label:"二十三、乐其可知也",showLabel:!0,sentences:[["子语鲁大师乐，曰：“乐其可知也。始作，",{text:"翕如",glossary:"xiru"},"也；从之，",{text:"纯如",glossary:"chunru"},"也，",{text:"皦如",glossary:"jiaoru"},"也，",{text:"绎如",glossary:"yiru"},"也，以成。”"]],note:"孔子与鲁国大师（乐官）论乐：「乐其可知也」——乐是可以知晓的。「始作，翕如也」（起奏时众音齐合），「从之，纯如也」（继而和谐纯一），「皦如也」（清晰分明），「绎如也」（连绵不绝），「以成」（如是而成）。以五词写乐之次第。"},{id:"ershisi",label:"二十四、天将以夫子为木铎",showLabel:!0,sentences:[["仪封人请见，曰：“君子之至于斯也，吾未尝不得见也。”从者见之。出曰：“二三子何患于丧乎？天下之无道也久矣，天将以夫子为",{text:"木铎",glossary:"muduo"},"。”"]],note:"仪地封人（守边之吏）求见孔子，说：「君子之至于斯也，吾未尝不得见也」——君子至此，我没有见不到的。见后出来说：「二三子何患于丧乎」——你们何必忧虑（失位／道之不行）？「天下之无道也久矣，天将以夫子为木铎」——天下无道已久了，上天将把夫子当作木铎（木铎＝摇以宣政教者）。"},{id:"ershiwu",label:"二十五、尽善尽美",showLabel:!0,sentences:[["子谓《韶》：“尽美矣，又尽善也。”谓《武》：“尽美矣，未尽善也。”"]],note:"孔子评《韶》：「尽美矣，又尽善也」——美极了，又善极了。评《武》：「尽美矣，未尽善也」——美极了，但未尽善。《韶》为舜乐，《武》为武王之乐；舜以德得天下，武王以征伐得天下，故有此差等。"},{id:"ershiliu",label:"二十六、吾何以观之哉",showLabel:!0,sentences:[["子曰：“居上不宽，为礼不敬，临丧不哀，吾何以观之哉？”"]],note:"「居上不宽，为礼不敬，临丧不哀，吾何以观之哉」——在上位而不宽厚，行礼而不恭敬，临丧而不哀戚，我还能看什么呢？三句皆言「有其事而无其心」，故无所可观。"}],r=[{id:"bayi",term:"八佾",pinyin:"bā yì",meaning:"佾：舞蹈的行列，每行八人。八佾为八行六十四人，是天子之礼；诸侯六佾，大夫四佾。季氏是鲁国大夫，用八佾即僭越。"},{id:"shu",term:"孰",pinyin:"shú",meaning:"什么。是可忍也，孰不可忍也：这样的事都能容忍，还有什么不能容忍？"},{id:"che",term:"彻",pinyin:"chè",meaning:"撤除祭品。祭毕撤馔时唱《雍》诗，此亦天子之礼。"},{id:"mumu",term:"穆穆",pinyin:"mù mù",meaning:"庄严肃穆之貌。语出《诗经·周颂·雍》。"},{id:"she",term:"奢",pinyin:"shē",meaning:"奢侈、铺张。礼与其铺张，不如俭朴。"},{id:"yi-sang",term:"易",pinyin:"yì",meaning:"此处指治丧轻慢、只重形式（一说「易」为「和易」，即哀不足）。与下文「戚」相对。"},{id:"qi",term:"戚",pinyin:"qī",meaning:"悲戚、哀伤。丧礼与其仪节周备而哀不足，不如真心哀戚。"},{id:"lv",term:"旅",pinyin:"lǚ",meaning:"祭名。诸侯祭祀境内名山大川为「旅」，季氏以大夫身份祭泰山，也是僭越。"},{id:"yirang",term:"揖让",pinyin:"yī ràng",meaning:"作揖谦让。射礼中先揖让而后升堂，争之中有礼。"},{id:"qian",term:"倩",pinyin:"qiàn",meaning:"笑时两颊现出酒窝的样子。语出《诗经·卫风·硕人》。"},{id:"pan",term:"盼",pinyin:"pàn",meaning:"眼睛黑白分明、流转有神。"},{id:"huishihousu",term:"绘事后素",pinyin:"huì shì hòu sù",meaning:"绘画之事在有了白色的底子之后。素：白底。喻先有本（忠信之质），后有末（礼）。"},{id:"wenxian",term:"文献",pinyin:"wén xiàn",meaning:"文：典籍；献：贤人（熟悉掌故的人）。此处「献」指人而非资料。"},{id:"di",term:"禘",pinyin:"dì",meaning:"天子祭祀始祖所自出之帝的大祭。鲁国以诸侯而行禘礼，亦属僭越，故孔子不愿观。"},{id:"guan",term:"灌",pinyin:"guàn",meaning:"同「祼」，禘祭开始时以酒灌地降神之礼。既灌之后，孔子便不想再看了。"},{id:"mei",term:"媚",pinyin:"mèi",meaning:"谄媚、讨好。"},{id:"ao",term:"奥",pinyin:"ào",meaning:"室内西南角，古时尊者所居，祭时设神主之处。喻有地位而无实权者。"},{id:"zao",term:"灶",pinyin:"zào",meaning:"灶神。喻有实权者。王孙贾以此暗问：该讨好谁？"},{id:"jian",term:"监",pinyin:"jiàn",meaning:"同「鉴」，借鉴。周监于二代：周代借鉴夏、殷两代。"},{id:"yuyuhuwenzai",term:"郁郁乎文哉",pinyin:"yù yù hū wén zāi",meaning:"多么丰富而有文采啊！郁郁：繁盛貌；文：礼乐典章之文明。"},{id:"zourenzhizi",term:"鄹人之子",pinyin:"zōu rén zhī zǐ",meaning:"鄹地人的儿子，指孔子（其父叔梁纥曾任鄹邑大夫）。此语略带轻慢。"},{id:"pi",term:"皮",pinyin:"pí",meaning:"箭靶。射不主皮：射礼重在中的与否、仪态是否合礼，不在射穿箭靶（那关乎力气）。"},{id:"xiyang",term:"饩羊",pinyin:"xì yáng",meaning:"告朔之礼所用的活羊。告朔：每月朔日告庙听政之礼。当时已废，仅存此羊。"},{id:"yin-yue",term:"淫",pinyin:"yín",meaning:"过度、放纵。乐而不淫：快乐而不过分。"},{id:"jiu",term:"咎",pinyin:"jiù",meaning:"追究、责备。既往不咎：已经过去的事不再追究。"},{id:"she-guan",term:"摄",pinyin:"shè",meaning:"兼任。官事不摄：管仲的家臣各司一职、不兼摄，因此用人多、开销大。"},{id:"saimen",term:"塞门",pinyin:"sài mén",meaning:"国君宫室前的照壁（屏风）。诸侯以上方可设，管仲亦设之，是僭越。"},{id:"fandian",term:"反坫",pinyin:"fǎn diàn",meaning:"两国国君宴饮后，放置空酒杯的土台。亦为诸侯之礼。"},{id:"xiru",term:"翕如",pinyin:"xī rú",meaning:"乐声初起时和谐聚合的样子。"},{id:"chunru",term:"纯如",pinyin:"chún rú",meaning:"乐声纯一、配合和谐的样子。"},{id:"jiaoru",term:"皦如",pinyin:"jiǎo rú",meaning:"节奏分明、清晰的样子。"},{id:"yiru",term:"绎如",pinyin:"yì rú",meaning:"连绵不断、余音相续的样子。"},{id:"muduo",term:"木铎",pinyin:"mù duó",meaning:"以木为舌的铜铃。古时宣布政令时摇木铎以警众。天将以夫子为木铎：上天要让孔子来警醒天下。"}];return(p,n)=>{const o=e("DaoTextReading"),l=e("DaoKeywordCards");return m(),h("div",null,[n[0]||(n[0]=i('<h1 id="论语·八佾" tabindex="-1">论语·八佾 <a class="header-anchor" href="#论语·八佾" aria-label="Permalink to &quot;论语·八佾&quot;">​</a></h1><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2><p>《八佾》全篇讲<strong>礼乐</strong>——这是《论语》里论礼最集中、也最深入的一篇。但它讲的不是仪节条目，而是礼的<strong>根</strong>：为什么要有礼、礼的本在哪里、礼崩之后还剩下什么。</p><p>全篇有一条对抗的线索：一边是季氏、三家用天子之礼、祭泰山、设塞门，<strong>层层僭越</strong>；一边是孔子在太庙「每事问」、在祭时「祭如在」、在射礼上看人不看力。两种态度之间，就是这一篇的分量所在。其中最动人的是第二十四章——仪封人见过孔子后说：「天下之无道也久矣，天将以夫子为木铎。」</p><p>默认竹简沉浸通读；切「经典阅读」可点生词。</p>',5)),a(o,{colophon:"八佾第三 · 二十六章",tone:"ink",sections:s,glossary:r,"default-mode":"slips","aria-label":"论语·八佾 原文"}),n[1]||(n[1]=t("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[u("【原典层】注音与字词 "),t("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),a(l,{items:[{term:"八佾",pinyin:["bā","yì"],meaning:"佾：舞蹈的行列，每行八人。八佾为八行六十四人，是天子之礼；诸侯六佾，大夫四佾。季氏是鲁国大夫，用八佾即僭越。"},{term:"孰",pinyin:["shú"],meaning:"什么。是可忍也，孰不可忍也：这样的事都能容忍，还有什么不能容忍？"},{term:"彻",pinyin:["chè"],meaning:"撤除祭品。祭毕撤馔时唱《雍》诗，此亦天子之礼。"},{term:"穆穆",pinyin:["mù","mù"],meaning:"庄严肃穆之貌。语出《诗经·周颂·雍》。"},{term:"奢",pinyin:["shē"],meaning:"奢侈、铺张。礼与其铺张，不如俭朴。"},{term:"易",pinyin:["yì"],meaning:"此处指治丧轻慢、只重形式（一说「易」为「和易」，即哀不足）。与下文「戚」相对。"},{term:"戚",pinyin:["qī"],meaning:"悲戚、哀伤。丧礼与其仪节周备而哀不足，不如真心哀戚。"},{term:"旅",pinyin:["lǚ"],meaning:"祭名。诸侯祭祀境内名山大川为「旅」，季氏以大夫身份祭泰山，也是僭越。"},{term:"揖让",pinyin:["yī","ràng"],meaning:"作揖谦让。射礼中先揖让而后升堂，争之中有礼。"},{term:"倩",pinyin:["qiàn"],meaning:"笑时两颊现出酒窝的样子。语出《诗经·卫风·硕人》。"},{term:"盼",pinyin:["pàn"],meaning:"眼睛黑白分明、流转有神。"},{term:"绘事后素",pinyin:["huì","shì","hòu","sù"],meaning:"绘画之事在有了白色的底子之后。素：白底。喻先有本（忠信之质），后有末（礼）。"},{term:"文献",pinyin:["wén","xiàn"],meaning:"文：典籍；献：贤人（熟悉掌故的人）。此处「献」指人而非资料。"},{term:"禘",pinyin:["dì"],meaning:"天子祭祀始祖所自出之帝的大祭。鲁国以诸侯而行禘礼，亦属僭越，故孔子不愿观。"},{term:"灌",pinyin:["guàn"],meaning:"同「祼」，禘祭开始时以酒灌地降神之礼。既灌之后，孔子便不想再看了。"},{term:"媚",pinyin:["mèi"],meaning:"谄媚、讨好。"},{term:"奥",pinyin:["ào"],meaning:"室内西南角，古时尊者所居，祭时设神主之处。喻有地位而无实权者。"},{term:"灶",pinyin:["zào"],meaning:"灶神。喻有实权者。王孙贾以此暗问：该讨好谁？"},{term:"监",pinyin:["jiàn"],meaning:"同「鉴」，借鉴。周监于二代：周代借鉴夏、殷两代。"},{term:"郁郁乎文哉",pinyin:["yù","yù","hū","wén","zāi"],meaning:"多么丰富而有文采啊！郁郁：繁盛貌；文：礼乐典章之文明。"},{term:"鄹人之子",pinyin:["zōu","rén","zhī","zǐ"],meaning:"鄹地人的儿子，指孔子（其父叔梁纥曾任鄹邑大夫）。此语略带轻慢。"},{term:"皮",pinyin:["pí"],meaning:"箭靶。射不主皮：射礼重在中的与否、仪态是否合礼，不在射穿箭靶（那关乎力气）。"},{term:"饩羊",pinyin:["xì","yáng"],meaning:"告朔之礼所用的活羊。告朔：每月朔日告庙听政之礼。当时已废，仅存此羊。"},{term:"淫",pinyin:["yín"],meaning:"过度、放纵。乐而不淫：快乐而不过分。"},{term:"咎",pinyin:["jiù"],meaning:"追究、责备。既往不咎：已经过去的事不再追究。"},{term:"摄",pinyin:["shè"],meaning:"兼任。官事不摄：管仲的家臣各司一职、不兼摄，因此用人多、开销大。"},{term:"塞门",pinyin:["sài","mén"],meaning:"国君宫室前的照壁（屏风）。诸侯以上方可设，管仲亦设之，是僭越。"},{term:"反坫",pinyin:["fǎn","diàn"],meaning:"两国国君宴饮后，放置空酒杯的土台。亦为诸侯之礼。"},{term:"翕如",pinyin:["xī","rú"],meaning:"乐声初起时和谐聚合的样子。"},{term:"纯如",pinyin:["chún","rú"],meaning:"乐声纯一、配合和谐的样子。"},{term:"皦如",pinyin:["jiǎo","rú"],meaning:"节奏分明、清晰的样子。"},{term:"绎如",pinyin:["yì","rú"],meaning:"连绵不断、余音相续的样子。"},{term:"木铎",pinyin:["mù","duó"],meaning:"以木为舌的铜铃。古时宣布政令时摇木铎以警众。天将以夫子为木铎：上天要让孔子来警醒天下。"}]}),n[2]||(n[2]=i('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>《八佾》二十六章，通篇讲<strong>礼乐</strong>，但锋芒全在礼的「本」。全篇有两条对立的线：</p><p>一条是<strong>僭越</strong>——季氏八佾舞于庭、三家唱《雍》彻、季氏旅于泰山、管仲设塞门反坫。这些人有的是权，缺的是「该不该」。孔子对这些事的评语一句比一句重：从「是可忍也，孰不可忍」，到「管氏而知礼，孰不知礼」。</p><p>另一条是<strong>守礼之实</strong>——林放问礼之本而孔子称「大哉问」；子入太庙每事问；祭如在，祭神如神在；射不主皮；《关雎》乐而不淫。这些讲的都不是仪式怎么做，而是<strong>做的时候心里有没有那个东西</strong>。</p><p>两条线合起来，就是这一篇的结论：<strong>礼不是一套动作，是一种内在的分寸。</strong></p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>它把「形式」和「真心」分得很清</strong>：「礼，与其奢也，宁俭；丧，与其易也，宁戚」——<strong>宁可简陋，不可虚假</strong>。这是对一切仪式化行为的根本提醒。</li><li><strong>它一句话点破文与质的关系</strong>：「绘事后素」——先有白色的底子，才能画画。子夏由此推出「礼后乎」，孔子大为称赞。<strong>忠信是本，礼是末；本立了，礼才有依附之处。</strong></li><li><strong>它说清了「参与」的意义</strong>：「吾不与祭，如不祭」——礼的价值不在于鬼神是否受飨，而在于<strong>你有没有真的在场</strong>。这句话用在今天任何一件事上都有力量。</li><li><strong>它反对把心思花在讨好上</strong>：「获罪于天，无所祷也」——王孙贾问该讨好奥神还是灶神，孔子的回答直接越过了这个问题：<strong>讨巧没有用，根本错了，怎么补都无用。</strong></li><li><strong>它给出了礼乐的极高标准</strong>：「《韶》尽美矣，又尽善也；《武》尽美矣，未尽善也」——美是形式，善是内涵。<strong>能两者兼得的，才是最高。</strong> 这也是中国艺术批评里「美善相兼」的源头。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>做仪式时问一句「我在不在场」</strong>：「祭如在」——开会、述职、参加红白事、陪家人吃饭时，人是到齐了，心在不在？不在场的形式，等于没做。</li><li><strong>检查自己在「撑场面」还是「有真心」</strong>：礼与其奢宁俭、丧与其易宁戚。<strong>场面是给别人的，戚是给自己的。</strong></li><li><strong>先有底子，再谈装饰</strong>：「绘事后素」——团队文化、个人品牌、作品风格，都得先有那个「素」。没有素，绚只是浮。</li><li><strong>别把心思花在揣摩上意</strong>：「获罪于天，无所祷也」——与其琢磨讨好谁，不如把根本的事做对。</li><li><strong>接纳「不够完美」</strong>：以射不主皮看人看己——力气有大小，各有各的科。<strong>标准要合于人力，尤其在带孩子、带团队时。</strong></li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>《八佾》一整篇都在说礼，但说的其实是一件更根本的事：<strong>一件事该以什么为本。</strong></p><p>孔子看到三种病。一种是把礼当排场——季氏用天子的舞，三家用天子的诗，礼成了炫耀。一种是把礼当摆设——告朔之礼只剩一只羊，形式还在，内容没了。一种是把礼当交易——该讨好奥神还是灶神，满脑子算计。</p><p>他的解药也只有一个字：<strong>本</strong>。礼的本在敬，在哀，在真心；先有那个素，才谈得上绚。所以礼与其奢侈，宁可俭朴；丧事与其周备，宁可悲戚。到最后，他用《韶》与《武》的区别作了总结——<strong>美可以做到，善也做到了，才算真的到位。</strong></p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「礼，与其奢也，宁俭；丧，与其易也，宁戚」——我在生活里更偏哪一头？是场面做足了心里空着，还是形式简陋但真在里面？</li><li>「绘事后素」——如果礼是后来的，那我这块「素」是忠信还是别的？我一直在画的画，底子够白吗？</li><li>「祭如在」「吾不与祭，如不祭」——我把「到场」和「在场」混为一谈过吗？哪些场合我人是到了，心没到？</li><li>「获罪于天，无所祷也」——我有没有过把心思放在琢磨人、而不是放在做事上的阶段？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上篇：<a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-02">论语·为政</a>　下篇：<a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-04">论语·里仁</a></li><li>参考：《论语》朱熹《四书章句集注·论语集注》；杨伯峻《论语译注》</li></ul>',21))])}}});export{c as __pageData,x as default};
